export function formatIsoDate(y, m, d) {
  return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
}

export function toIsoDateString({year, month, day} = {}) {
  if (!year || !month || !day) throw new TypeError('INVALID_DATE_OBJECT');
  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

export function formatYuan(cents, options = {currencySymbol: '¥'}) {
  if (typeof options !== 'object' || options === null) {
    throw new TypeError('OPTIONS_MUST_BE_OBJECT');
  }
  const sym = options.currencySymbol ?? '¥';
  return `${sym}${(cents / 100).toFixed(2)}`;
}

import {formatIsoDate} from './vendor/date-v1.mjs';
import {formatYuan} from './vendor/money-v1.mjs';

export function buildDailySummary({year, month, day, totalCents}) {
  const dateStr = formatIsoDate(year, month, day);
  const amountStr = formatYuan(totalCents, '¥');
  return `${dateStr}: ${amountStr}`;
}

