import {parseKv} from './lib/loader-v1.mjs';
import {validatePort} from './lib/validator-v1.mjs';

export function loadAppConfig(rawText) {
  const entries = parseKv(rawText);
  const obj = Object.fromEntries(entries);
  const port = Number(obj.PORT || 8080);
  if (!validatePort(port)) throw new Error('BAD_PORT');
  return {host: obj.HOST || '127.0.0.1', port};
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {loadAppConfig} from '../src/app-config.mjs';

test('loads HOST and PORT=8080', () => {
  assert.deepEqual(loadAppConfig('HOST=0.0.0.0\nPORT=8080'), {host: '0.0.0.0', port: 8080});
});
